#include <stdio.h>
#include <stdlib.h>
int main(void) {
 size_t count = 3;
 int *items = malloc(count * sizeof *items);
 if (items == NULL) {
  fputs("allocation failed\n", stderr);
  return 1;
 }
 for (size_t i=0; i<count; ++i) items[i] = (int)i + 1;
 printf("last=%d\n", items[count - 1]);
 free(items);
 return 0;
}
